    "claims": [
      {
        "statement": "The business operates under the name Boise Metal Works and has been operating since 1994.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/",
        "quote": "Since 1994. High-Quality Metal Fabrication in Boise, Idaho and Surrounding Areas"
