      {
        "statement": "Boise Metal Works is located at 2000 Yamhill Rd., Boise, ID 83716.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/",
        "quote": "2000 Yamhill Rd. Boise, ID 83716 [redacted]"
      },
      {
        "statement": "Boise Metal Works was founded in 1994 by [redacted] and [redacted], originating from the [redacted] family's Boise Spring Works founded in 1917.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/idaho-master-metal-fabricators-history/",
        "quote": "Boise Metal Works was spawned from Boise Spring Works , which had been founded by [redacted] in 1917."
      },
      {
        "statement": "The company serves Boise, the Treasure Valley communities of Meridian, Eagle, Nampa, and Caldwell, as well as Eastern Oregon.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/contact/",
        "quote": "We have been serving Boise, Idaho including the Treasure Valley Communities of Meridian, Eagle, Nampa – Caldwell and Eastern Oregon since 1994."
      }
    ]
  },
  "industry": {
    "industry": "Custom Metal Fabrication and Manufacturing",
    "activities": [
      "Custom metal fabrication for commercial, industrial, and residential applications",
      "Structural steel fabrication",
      "Custom metal railing, stairs, gates, fences, awnings, and signs",
      "Custom truck accessories and fabricated steel tanks",
      "Product development, value engineering, and manufacturing runs",
      "CNC machining and CNC water jet cutting",
      "In-house painting and partnered powder coating"
    ],
    "claims": [
      {
        "statement": "Boise Metal Works provides custom metal fabrication and manufacturing solutions for commercial, industrial, and residential applications.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/",
        "quote": "Boise Metal Works provides custom metal fabrication and manufacturing solutions for commercial, industrial, and residential applications."
      },
      {
        "statement": "The company provides structural steel fabrication, including main structural members, stairways, safety bollards, steel concrete embeds, and OSHA guards, rails, ladders, and platforms.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/structural-steel-fabrication-idaho/",
        "quote": "Boise Metal Works provides structural steel fabrication, everything for your structural steel projects, from the main structural members down to the miscellaneous items"
      },
      {
        "statement": "The company offers value engineering and manufacturing support for general contractors, entrepreneurs, and competitors.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/product-development-manufacturing/",
        "quote": "Boise Metal Works provides value engineering services to General Contractors and entrepreneurs which allows for options within the metal fabrication work scope"
      },
      {
        "statement": "Boise Metal Works is a metal fabrication and manufacturing business rather than an HVAC, plumbing, or electrical home-service contractor.",
        "label": "inference",
        "sourceUrl": "https://www.boisemetalworks.com/",
        "quote": null
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://www.boisemetalworks.com/",
    "claims": [
      {
        "statement": "The company's public website lists a base shop rate of $95 per hour, separate from machining and water jet rates.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/metals-fabrication-industry-infomation/",
        "quote": "Our shop rate is $95 an hour and is subject to change. This is separate from our machining and water jet rates."
      },
      {
        "statement": "The shop's stated equipment includes steel shearing and forming machines, a 110-ton iron worker, a Vf4 CNC machine, and a 9' x 13' CNC water jet machine.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/metal-fabrication-shop-capacities/",
        "quote": "We can cut up to 12′ of Mild Steel. We have a table size of 9′ x 13′."
      },
      {
        "statement": "Each customer is assigned a dedicated point of contact from design through delivery.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/",
        "quote": "Your dedicated, Boise Metal Works point of contact is committed for the life of your project, from design to delivery."
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "The structural steel page states that the company has experienced and certified welders and technicians for on-site fabrication, repairs, and maintenance.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/structural-steel-fabrication-idaho/",
        "quote": "Experienced & certified welders and technicians for on-site fabrication, repairs and maintenance."
