  "problems": [
    {
      "problem": "Custom quote requests submitted through the web form with attached design files or sketches may require manual triage, estimation, and follow-up tracking.",
      "label": "hypothesis",
      "basis": "The website uses a basic web form with file upload for custom project inquiries and shows no client portal or automated quoting/scheduling integration on the public pages."
    },
    {
      "problem": "Supplier material invoices and job costing across custom fabrication, machining, water jetting, and partnered powder coating may involve manual data entry.",
      "label": "hypothesis",
      "basis": "The company performs multi-step custom fabrication and works with external powder coating partners, though its internal ERP or accounting software is not visible on the website."
    }
  ],
